def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Uniform rows encode a repeating vertical sequence. Find the shortest
    # period consistent with all observed rows, then extend it through blanks.
    uniform = [
        (r, row[0]) for r, row in enumerate(grid)
        if row[0] != 0 and all(v == row[0] for v in row)
    ]
    if uniform:
        for p in range(1, h + 1):
            if all((b - a) % p == 0 or (b - a) % p != 0
                   for a, _ in uniform for b, _ in uniform):
                if all(
                    (v1 == v2) if (r1 - r2) % p == 0 else True
                    for r1, v1 in uniform for r2, v2 in uniform
                ):
                    # Require the period to align every pair of known rows.
                    if all(
                        (r1 - r2) % p != 0 or v1 == v2
                        for r1, v1 in uniform for r2, v2 in uniform
                    ):
                        break
        for r in range(h):
            known = [(rr, v) for rr, v in uniform if (rr - r) % p == 0]
            if known:
                v = known[0][1]
                out[r] = [v] * w
        return out

    # Otherwise the colors repeat along diagonals running down-right.
    vals = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                k = (c - r) % w
                vals.setdefault(k, grid[r][c])
    if vals:
        for r in range(h):
            for c in range(w):
                k = (c - r) % w
                if k in vals:
                    out[r][c] = vals[k]
    return out
